out<-'tmp/rank-effect-errors-i18n';dir.create(out,recursive=TRUE,showWarnings=FALSE)
base<-list(effect_size_nonparametric_n1='10',effect_size_nonparametric_n2='20',effect_size_nonparametric_n='30',effect_size_nonparametric_chi_square='12',effect_size_nonparametric_measurements='2')
calc<-function(changes) suppressWarnings(effect_size_nonparametric_calculate(modifyList(base,changes)))
errors<-lapply(c('201','400'),function(u)calc(list(effect_size_nonparametric_design='rank_biserial_from_u',effect_size_nonparametric_u=u)))
errors<-c(errors,lapply(c('1','0','NaN','Inf'),function(m)calc(list(effect_size_nonparametric_design='friedman_w',effect_size_nonparametric_measurements=m))))
keys<-paste0('sample_size.result.',c(rep('error_mann_whitney_limit',2),rep('error_friedman_measurements',4)))
before_errors<-serialize(errors,NULL)
for(lang in c('en','ko','ja','zh','es','fr','de','vi'))for(i in seq_along(errors)){
 stopifnot(identical(errors[[i]]$error,statedu_t(keys[i],'en')))
 expected<-statedu_t(keys[i],lang,fallback='')
 actual<-xml2::xml_text(xml2::xml_find_first(xml2::read_html(as.character(sample_size_results_ui(errors[[i]],lang))),'//div[@class="analysis-warning"]'))
 stopifnot(nzchar(expected),identical(actual,expected));if(lang!='en')stopifnot(actual!=errors[[i]]$error)
 unknown<-paste0(errors[[i]]$error,' custom');stopifnot(identical(sample_size_result_text(unknown,lang),unknown))
}
stopifnot(identical(before_errors,serialize(errors,NULL)))
results<-c(lapply(c(50,100,200),function(u)calc(list(effect_size_nonparametric_design='rank_biserial_from_u',effect_size_nonparametric_u=as.character(u)))),lapply(c(12,60),function(chisq)calc(list(effect_size_nonparametric_design='friedman_w',effect_size_nonparametric_chi_square=as.character(chisq)))))
expected<-c(-.5,0,1,.4,1)
for(i in seq_along(results))stopifnot(is.null(results[[i]]$error),isTRUE(all.equal(results[[i]]$primary_effect_size,expected[i])))
for(i in 1:3)stopifnot(identical(results[[i]]$rank_biserial,results[[i]]$cliffs_delta))
designs<-c('U50','U100','U200-boundary','Friedman-two','Friedman-cap');formula_keys<-paste0('sample_size.result.',c(rep('note_rank_orientation',3),rep('kendall',2)))
cat('PASS six actual rank-effect errors x eight languages; U upper-bound, negative/zero orientation and Kendall-W cap references\n')
